"""Türkçe — iman ve ibadet (faith_001 … faith_070)."""

T = {
"faith_001": ("İslam'ın kaç şartı vardır?", ["5", "4", "6", "7"], "Cebrail hadisi ve İbn Ömer'in rivayet ettiği hadis İslam'ın beş şartını sayar."),
"faith_002": ("İslam'da iman beyanına ne denir?", ["Kelime-i şehadet", "Namaz", "Zekât", "Hac"], "Kelime-i şehadet, iman tanıklığı, İslam'ın ilk şartıdır."),
"faith_003": ("İslam'da farz namaz günde kaç kez kılınır?", ["5", "3", "4", "7"], "Günde beş vakit farz namaz İslam'ın temel şartlarındandır."),
"faith_004": ("İslam'da zorunlu sadakaya ne denir?", ["Zekât", "Sadaka", "Vakıf", "Kefaret"], "Zekât, İslam'ın beş şartından biri olan zorunlu sadakadır."),
"faith_005": ("İslam'da farz oruç ayına ne denir?", ["Ramazan", "Şevval", "Recep", "Muharrem"], "Kur'an, Ramazan ayında oruç tutmayı emreder."),
"faith_006": ("Gücü yetene ömründe bir kez farz olan Mekke ziyaretine ne denir?", ["Hac", "Umre", "İtikâf", "Tavaf"], "Kur'an, gücü yeten herkese ömründe en az bir kez haccı farz kılar."),
"faith_007": ("Müslümanlar namazda hangi yöne dönerler?", ["Mekke'deki Kâbe'ye", "Kudüs'e", "Medine'ye", "Doğuya"], "Kur'an, Kâbe'yi namazın yönü (kıble) olarak belirledi."),
"faith_008": ("Meşhur bir hadise göre genellikle kaç iman esası öğretilir?", ["6", "4", "5", "7"], "Cebrail hadisi altı iman esasını sayar: Allah, melekler, kitaplar, peygamberler, ahiret günü ve kader."),
"faith_009": ("Müslümanın her namazdan önce suyla yaptığı temizliğe ne denir?", ["Abdest", "Teyemmüm", "Gusül", "Misvak"], "«Namaza kalktığınızda yüzlerinizi ve ellerinizi yıkayın…»: bu abdesttir."),
"faith_010": ("Kur'an'a göre «değerli yazıcılar» (kirâmen kâtibîn) ne yapar?", ["İnsanların amellerini kaydederler", "Arşı taşırlar", "Cenneti beklerler", "Yağmur getirirler"], "«Üzerinizde koruyucular, değerli yazıcılar var»: melekler her ameli kaydeder."),
"faith_011": ("Sahih rivayet Allah'ın kaç güzel ismini bildirir?", ["99", "50", "100", "114"], "Buhârî ve Müslim'in rivayet ettiği sahih bir hadis doksan dokuz isim zikreder: yüzden bir eksik."),
"faith_012": ("Allah'ın «Rahman» ismi ne anlama gelir?", ["Rahmeti bol olan", "Yaratan", "Melik", "Her şeyi bilen"], "Rahman, rahmeti bol olan: rahmeti her şeyi kuşatır."),
"faith_013": ("Fatiha'da Allah hangi günün «Sahibi» olarak anılır?", ["Din (hesap) gününün", "Cumanın", "İlk günün", "Arefe gününün"], "«Din gününün sahibi»: herkesin amelleriyle karşılaştığı gün."),
"faith_014": ("Kur'an müminleri haftanın hangi günü toplu namaza çağırır?", ["Cuma", "Pazartesi", "Cumartesi", "Pazar"], "«Cuma günü namaza çağrıldığında Allah'ı anmaya koşun.»"),
"faith_015": ("Kur'an'a göre Kur'an'ın her türlü tahriften korunmasını kim garanti eder?", ["Allah'ın kendisi", "Yalnızca melekler", "Âlimler", "Krallar"], "«Şüphesiz Zikr'i biz indirdik ve onu koruyacak olan da biziz.»"),
"faith_016": ("Kur'an dine girme konusunda ne bildirir?", ["Dinde zorlama yoktur", "Yeminle olur", "Şahit gerekir", "Ergenlikte olur"], "«Dinde zorlama yoktur: doğru yol sapıklıktan ayrılmıştır.»"),
"faith_017": ("Müslümanların bir barış dileği olan selamı nedir?", ["Es-selâmü aleyküm", "Merhaba", "Sabah'ul-hayr", "Ehlen ve sehlen"], "«Es-selâmü aleyküm»: selam üzerinize olsun; cevabı «ve aleykümü's-selâm»dır."),
"faith_018": ("İslam'ın özü olan Allah'ın birliğine inanca ne denir?", ["Tevhid", "Tefsir", "Tecvid", "Teravih"], "Tevhid, Allah'ın ortaksız Bir olduğunu tasdik etmek, bütün imanın temelidir."),
"faith_019": ("Allah Musa peygambere hangi kitabı indirdi?", ["Tevrat", "İncil", "Zebur", "Kur'an"], "«Tevrat'ı indirdik; onda hidayet ve nur vardır» (5:44)."),
"faith_020": ("Allah İsa peygambere hangi kitabı verdi?", ["İncil", "Tevrat", "Zebur", "İbrahim'in sahifeleri"], "«Ona içinde hidayet ve nur bulunan İncil'i verdik» (5:46)."),
"faith_021": ("Kur'an'a göre bir selam alındığında ne yapılmalıdır?", ["Daha güzeliyle karşılık vermek ya da aynıyla iade etmek", "Sessiz kalmak", "Gözleri indirmek", "Yalnızca dostlara cevap vermek"], "«Size bir selam verildiğinde ondan daha güzeliyle selam verin ya da aynıyla karşılık verin» (4:86)."),
"faith_022": ("A'lâ suresi hangi iki peygamberin «sahifelerini» anar?", ["İbrahim ve Musa", "Nuh ve Hud", "Davud ve Süleyman", "Zekeriya ve Yahya"], "«Şüphesiz bu, ilk sahifelerde, İbrahim'in ve Musa'nın sahifelerinde vardır» (87:18-19)."),
"faith_023": ("Kur'an'da anılan cehennem bekçisi meleğin adı nedir?", ["Malik", "Rıdvan", "Mikail", "İsrafil"], "Cehennemlikler seslenir: «Ey Malik, Rabbin bizim işimizi bitirsin!» (43:77)."),
"faith_024": ("Hâkka suresine göre kıyamet günü Allah'ın Arşını kaç melek taşıyacak?", ["Sekiz", "Dört", "On iki", "Bir"], "«O gün Rabbinin Arşını üstlerinde sekiz melek taşır» (69:17)."),
"faith_025": ("Kur'an'a göre ölüm anında canları almakla kim görevlidir?", ["Ölüm meleği", "Cebrail", "Peygamber", "Cinler"], "«De ki: size vekil kılınan ölüm meleği canınızı alacak» (32:11)."),
"faith_026": ("Sahih-i Müslim'deki bir hadise göre melekler neyden yaratıldı?", ["Nurdan", "Ateşten", "Çamurdan", "Sudan"], "«Melekler nurdan, cinler dumansız ateşten, Âdem ise size anlatılandan yaratıldı.»"),
"faith_027": ("Kur'an'a göre cinler neyden yaratıldı?", ["Dumansız ateşten", "Nurdan", "Çamurdan", "Rüzgârdan"], "«Cinleri de dumansız bir ateş alevinden yarattı» (55:15)."),
"faith_028": ("Kur'an kimi insanın açık düşmanı olarak niteler?", ["Şeytanı", "Melekleri", "Hayvanları", "Geceyi"], "«Şüphesiz şeytan sizin düşmanınızdır; siz de onu düşman edinin» (35:6)."),
"faith_029": ("Kaç peygambere «ülü'l-azm» (azim sahipleri) denir?", ["Beş: Nuh, İbrahim, Musa, İsa ve Muhammed ﷺ", "Üç", "On", "Yirmi beş"], "«Azim sahibi peygamberlerin sabrettiği gibi sabret» (46:35); Şûrâ suresi (42:13) bu beşini birlikte anar."),
"faith_030": ("Kur'an'a göre kıyameti haber vermek için neye üflenecek?", ["Sûr'a", "Koç boynuzuna", "Neye", "Çana"], "«Sûr'a üflenir, göklerde ve yerde olanlar düşüp ölür… sonra ona bir daha üflenir» (39:68)."),
"faith_031": ("Kur'an kıyamet günü amelleri tartacak olana ne der?", ["Mizanlar (teraziler)", "Sicil", "Köprü", "Sûr"], "«Kıyamet günü adalet terazilerini kurarız; hiç kimseye zerre kadar haksızlık edilmez» (21:47)."),
"faith_032": ("Kur'an, iman edip salih amel işleyenlere vaat edilen cennetin en yüksek derecesine ne ad verir?", ["Firdevs", "Kevser", "Sırat", "A'raf"], "«İman edip salih amel işleyenlere konak olarak Firdevs cennetleri vardır» (18:107)."),
"faith_033": ("Kur'an'da cehennemin en sık geçen adı nedir?", ["Cehennem", "Firdevs", "Kevser", "Tesnim"], "Kur'an cehennemi onlarca kez «cehennem» diye anar, örneğin: «Cehenneme toplanacaksınız» (3:12)."),
"faith_034": ("«Biz her şeyi bir ölçüye göre yarattık» ayeti hangi iman esasını doğrular?", ["Kadere imanı", "Meleklere imanı", "Kitaplara imanı", "Peygamberlere imanı"], "«Biz her şeyi bir ölçüye (kader) göre yarattık» (54:49): hiçbir şey Allah'ın ilmi ve iradesi dışında olmaz."),
"faith_035": ("Allah, tövbe etmeden ölene hangi günahı bağışlamayacağını bildirir?", ["Şirki (Allah'a ortak koşmayı)", "Yalanı", "Cimriliği", "Öfkeyi"], "«Allah kendisine ortak koşulmasını bağışlamaz; bunun dışındakini dilediğine bağışlar» (4:48)."),
"faith_036": ("Kur'an'a göre Allah günah işleyenler arasından kimleri sever?", ["Tövbe edenleri", "Günahlarını gizleyenleri", "Ümitsizliğe düşenleri", "Başkalarını suçlayanları"], "«Şüphesiz Allah çok tövbe edenleri sever, temizlenenleri de sever» (2:222)."),
"faith_037": ("Nuh suresine göre istiğfar bir kavme ne getirir?", ["Bol yağmur ve bereket", "Hiçbir şey", "Kuraklık", "Uzun bir uyku"], "«Rabbinizden bağışlanma dileyin; O çok bağışlayandır. Üzerinize gökten bol yağmur gönderir» (71:10-11)."),
"faith_038": ("Kur'an, Allah'a tevekkül edene ne vaat eder?", ["Allah ona yeter", "Zengin olur", "Hiç hastalanmaz", "Artık çalışması gerekmez"], "«Kim Allah'a tevekkül ederse O ona yeter» (65:3)."),
"faith_039": ("Allah Gâfir suresinde dua hakkında ne der?", ["«Bana dua edin, size karşılık vereyim»", "«Yalnızca gece dua edin»", "«Meleklere dua edin»", "«Dua yalnızca peygamberler içindir»"], "«Rabbiniz dedi ki: Bana dua edin, size karşılık vereyim» (40:60)."),
"faith_040": ("Kur'an'a göre kalpler neyle huzur bulur?", ["Allah'ı anmakla (zikir)", "Parayla", "Uykuyla", "Yolculukla"], "«Bilesiniz ki kalpler ancak Allah'ı anmakla huzur bulur» (13:28)."),
"faith_041": ("Günün ilk farz namazı hangisidir?", ["Sabah (fecr)", "Öğle", "İkindi", "Yatsı"], "Beş vakit namaz sırayla: sabah, öğle, ikindi, akşam ve yatsı."),
"faith_042": ("Sabah namazının farzı kaç rekâttır?", ["İki", "Üç", "Dört", "Bir"], "Sabahın farzı iki rekât; akşam üç; öğle, ikindi ve yatsı dörder rekâttır."),
"faith_043": ("Hangi farz namaz üç rekâttır?", ["Akşam", "Sabah", "Öğle", "Yatsı"], "Güneş battıktan hemen sonra kılınan akşam namazı, üç rekâtlık tek farz namazdır."),
"faith_044": ("Camiden yapılan namaza çağrıya ne denir?", ["Ezan", "Hutbe", "Tesbih", "Telbiye"], "Ezan, beş vakit namazın her birinden önce müezzin tarafından okunur."),
"faith_045": ("Abdest ayetine göre kollar nereye kadar yıkanmalıdır?", ["Dirseklere kadar", "Bileklere kadar", "Omuzlara kadar", "Yalnızca eller"], "«Yüzlerinizi ve dirseklere kadar ellerinizi yıkayın, başlarınızı mesh edin, topuklara kadar ayaklarınızı yıkayın» (5:6)."),
"faith_046": ("Kur'an, namazdan önce temizlenmek için su bulunamadığında neye izin verir?", ["Temiz toprakla teyemmüme", "Temizlenmeden namaza", "Namazı ertesi güne ertelemeye", "Islak kumla yıkanmaya"], "«Su bulamazsanız temiz toprağa yönelin; yüzlerinize ve ellerinize sürün» (5:6)."),
"faith_047": ("İmamın cuma namazından önce verdiği vaaza ne denir?", ["Hutbe", "Ezan", "Kamet", "Tekbir"], "Cuma hutbesi namazdan önce minberden iki bölüm halinde verilir."),
"faith_048": ("Müslüman, bir yıl boyunca elinde tuttuğu birikiminin ne kadarını zekât olarak verir?", ["%2,5", "%10", "%25", "%1"], "Birikmiş paranın zekâtı, nisabı aşıp üzerinden bir kameri yıl geçince kırkta bir, yani %2,5'tir."),
"faith_049": ("Ramazan sonunda, bayram namazından önce hangi özel sadaka verilir?", ["Fitre (zekâtü'l-fıtr)", "Altın zekâtı", "Humus", "Kefaret"], "Peygamber ﷺ fitreyi küçük büyük her Müslümana bir sâ' hurma veya arpa olarak farz kıldı."),
"faith_050": ("Kur'an'a göre Ramazan'da günlük oruç ne zamandan ne zamana kadar sürer?", ["Fecirden geceye kadar", "Öğleden akşama kadar", "Güneş doğuşundan öğlene kadar", "Bütün gün ve bütün gece"], "«Fecrin beyaz ipliği siyah iplikten ayırt edilinceye kadar yiyin için, sonra orucu geceye kadar tamamlayın» (2:187)."),
"faith_051": ("Oruç tutacak kişinin fecirden önce yediği yemeğe ne denir?", ["Sahur", "İftar", "Velime", "Akika"], "Peygamber ﷺ dedi ki: «Sahur yapın, çünkü sahurda bereket vardır.»"),
"faith_052": ("Güneş batınca orucu açan yemeğe ne denir?", ["İftar", "Sahur", "Teravih", "Teheccüd"], "İftar, güneş batar batmaz, akşam namazı vaktinde orucu açar."),
"faith_053": ("İslam'da yılda kaç bayram vardır?", ["İki: Ramazan ve Kurban Bayramı", "Yalnızca bir", "Dört", "On iki"], "Ramazan Bayramı Ramazan ayını kapatır; Kurban Bayramı hac sırasında 10 Zilhicce'dedir."),
"faith_054": ("Kurban Bayramı hangi olayı anar?", ["İbrahim'in bir koçla fidye verilen kurbanını", "Peygamber ﷺ'in doğumunu", "Bedir Savaşı'nı", "Kur'an'ın inişini"], "Oğlunu kurban etmeye hazır olan İbrahim, onun fidye ile kurtarıldığını gördü: «Ona büyük bir kurbanı fidye verdik» (37:107)."),
"faith_055": ("Hac, İslam takviminin hangi ayında yapılır?", ["Zilhicce", "Ramazan", "Muharrem", "Recep"], "Hac, kameri yılın on ikinci ve son ayı Zilhicce'nin 8-13. günlerinde yapılır."),
"faith_056": ("Hacılar Zilhicce'nin hangi günü Arafat ovasında vakfe yapar?", ["9'unda", "1'inde", "10'unda", "27'sinde"], "9 Zilhicce'de Arafat vakfesi haccın en büyük rüknüdür; ertesi gün Kurban Bayramı'dır."),
"faith_057": ("Bir tavaf Kâbe'nin etrafında kaç turdur?", ["Yedi", "Üç", "Beş", "On"], "Tavaf, Hacerülesved'den başlayarak saat yönünün tersine Kâbe'nin etrafında yedi turdur."),
"faith_058": ("Sa'y, Safa ile Merve arasında kaç gidiş-geliştir?", ["Yedi", "İki", "Dört", "On iki"], "Sa'y, Hacer'in İsmail için su arayışını anar: Safa'dan Merve'ye ve geri, her yön bir sayılarak yedi şavt."),
"faith_059": ("Hacının iki beyaz örtüsüyle girdiği kutsallık haline ne denir?", ["İhram", "Tavaf", "Vakfe", "Telbiye"], "İhramda erkek iki dikişsiz örtü giyer; hacı koku, av ve tartışmadan kaçınır."),
"faith_060": ("Hacıların Mekke yolunda tekrarladığı telbiye hangi sözlerle başlar?", ["«Lebbeyk Allahümme lebbeyk» (Buyur Allah'ım, buyur)", "«Allahu ekber»", "«Sübhanallah»", "«Elhamdülillah»"], "Peygamber ﷺ'in telbiyesi şöyleydi: «Lebbeyk Allahümme lebbeyk, lebbeyke lâ şerîke leke lebbeyk…»"),
"faith_061": ("Hacılar Mina'da üç sütuna taş atarken ne yaparlar?", ["Şeytan taşlama (cemerat)", "Tavaf", "Sa'y", "Arafat vakfesi"], "Cemerat, İbrahim'in şeytanı taşla kovmasını anar; bayram günlerinde Mina'da yapılır."),
"faith_062": ("Hacerülesved (Kara Taş) nerededir?", ["Kâbe'nin bir köşesinde", "Arafat dağında", "Medine'de", "Hira dağının zirvesinde"], "Kâbe'nin doğu köşesine yerleştirilmiş olup her tavaf turunun başlangıç noktasıdır."),
"faith_063": ("Kâbe'yi örten büyük siyah örtüye ne denir?", ["Kisve", "Hicap", "Minber", "Mihrap"], "Altın iplikle ayetler işlenmiş kisve, her yıl hac sırasında yenilenir."),
"faith_064": ("Yılın herhangi bir zamanında yapılabilen «küçük» Mekke ziyaretine ne denir?", ["Umre", "Hac", "Hicret", "Ziyaret"], "Umre ihram, tavaf ve sa'yden oluşur; hacdan farklı olarak belirli bir aya bağlı değildir."),
"faith_065": ("Allah'ın «Hâlık» ismi ne anlama gelir?", ["Yaratan", "Bağışlayan", "Rızık veren", "Melik"], "«O, yaratan (Hâlık), var eden, şekil veren Allah'tır» (59:24)."),
"faith_066": ("Allah'ın «Gafûr» ismi ne anlama gelir?", ["Çok bağışlayan", "Yaratan", "Her şeye gücü yeten", "Cömert"], "«Allah'ın rahmetinden ümit kesmeyin… O çok bağışlayan (Gafûr), çok merhamet edendir» (39:53)."),
"faith_067": ("Allah'ın «Semî'» ve «Basîr» isimleri ne anlama gelir?", ["Her şeyi işiten ve her şeyi gören", "Melik ve Hakem", "Yaratan ve Rızık veren", "Evvel ve Âhir"], "İsra ayeti şöyle biter: «Şüphesiz O işitendir (Semî'), görendir (Basîr)» (17:1)."),
"faith_068": ("İhlas suresindeki «Samed» ismi ne anlama gelir?", ["Her şeyin kendisine muhtaç olduğu, hiçbir şeye muhtaç olmayan", "Bağışlayan", "İşiten", "Yaratan"], "«Allahü's-Samed» (112:2): bütün yaratılmışların ihtiyaçlarında yöneldiği mutlak Efendi."),
"faith_069": ("Âyetü'l-Kürsî «Allah, O'ndan başka ilah yoktur» dedikten hemen sonra Allah'ın hangi iki ismiyle devam eder?", ["Hayy ve Kayyûm (diri, her şeyi ayakta tutan)", "Rahman ve Rahîm", "Melik ve Kuddûs", "Azîz ve Hakîm"], "«Allah, O'ndan başka ilah yoktur; Hayy'dır, Kayyûm'dur» (2:255)."),
"faith_070": ("Allah'ın «Rezzâk» ismi ne anlama gelir?", ["Bol rızık veren", "Bağışlayan", "Adil", "Latif"], "«Şüphesiz Allah rızık verendir (Rezzâk), güç sahibidir, sarsılmazdır» (51:58)."),
}
